def squash(s: str) -> str:
    if not s:
        return ""

    def esc(c: str) -> str:
        if c.isdigit() or c == "\\":
            return "\\" + c
        return c

    result = []
    n = len(s)
    i = 0

    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        length = j - i
        char = s[i]
        escaped_char = esc(char)

        if length >= 3:
            result.append(f"{length}{escaped_char}")
        else:
            result.append(escaped_char * length)

        i = j

    return "".join(result)
